-- Permission vocabulary and system roles of the learning module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the learning permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('competency:create'::text, 'competency'::text, 'create'::text, 'Create competency'::text),
            ('competency:delete'::text, 'competency'::text, 'delete'::text, 'Delete competency'::text),
            ('competency:purge'::text, 'competency'::text, 'purge'::text, 'Purge competency'::text),
            ('competency:read'::text, 'competency'::text, 'read'::text, 'Read competency'::text),
            ('competency:restore'::text, 'competency'::text, 'restore'::text, 'Restore competency'::text),
            ('competency:update'::text, 'competency'::text, 'update'::text, 'Update competency'::text),
            ('course:create'::text, 'course'::text, 'create'::text, 'Create course'::text),
            ('course:delete'::text, 'course'::text, 'delete'::text, 'Delete course'::text),
            ('course:purge'::text, 'course'::text, 'purge'::text, 'Purge course'::text),
            ('course:read'::text, 'course'::text, 'read'::text, 'Read course'::text),
            ('course:restore'::text, 'course'::text, 'restore'::text, 'Restore course'::text),
            ('course:update'::text, 'course'::text, 'update'::text, 'Update course'::text),
            ('course_enrollment:create'::text, 'course_enrollment'::text, 'create'::text, 'Create course enrollment'::text),
            ('course_enrollment:delete'::text, 'course_enrollment'::text, 'delete'::text, 'Delete course enrollment'::text),
            ('course_enrollment:purge'::text, 'course_enrollment'::text, 'purge'::text, 'Purge course enrollment'::text),
            ('course_enrollment:read'::text, 'course_enrollment'::text, 'read'::text, 'Read course enrollment'::text),
            ('course_enrollment:restore'::text, 'course_enrollment'::text, 'restore'::text, 'Restore course enrollment'::text),
            ('course_enrollment:update'::text, 'course_enrollment'::text, 'update'::text, 'Update course enrollment'::text),
            ('employee_competency:create'::text, 'employee_competency'::text, 'create'::text, 'Create employee competency'::text),
            ('employee_competency:delete'::text, 'employee_competency'::text, 'delete'::text, 'Delete employee competency'::text),
            ('employee_competency:purge'::text, 'employee_competency'::text, 'purge'::text, 'Purge employee competency'::text),
            ('employee_competency:read'::text, 'employee_competency'::text, 'read'::text, 'Read employee competency'::text),
            ('employee_competency:restore'::text, 'employee_competency'::text, 'restore'::text, 'Restore employee competency'::text),
            ('employee_competency:update'::text, 'employee_competency'::text, 'update'::text, 'Update employee competency'::text),
            ('employee_skill:create'::text, 'employee_skill'::text, 'create'::text, 'Create employee skill'::text),
            ('employee_skill:delete'::text, 'employee_skill'::text, 'delete'::text, 'Delete employee skill'::text),
            ('employee_skill:purge'::text, 'employee_skill'::text, 'purge'::text, 'Purge employee skill'::text),
            ('employee_skill:read'::text, 'employee_skill'::text, 'read'::text, 'Read employee skill'::text),
            ('employee_skill:restore'::text, 'employee_skill'::text, 'restore'::text, 'Restore employee skill'::text),
            ('employee_skill:update'::text, 'employee_skill'::text, 'update'::text, 'Update employee skill'::text),
            ('skill:create'::text, 'skill'::text, 'create'::text, 'Create skill'::text),
            ('skill:delete'::text, 'skill'::text, 'delete'::text, 'Delete skill'::text),
            ('skill:purge'::text, 'skill'::text, 'purge'::text, 'Purge skill'::text),
            ('skill:read'::text, 'skill'::text, 'read'::text, 'Read skill'::text),
            ('skill:restore'::text, 'skill'::text, 'restore'::text, 'Restore skill'::text),
            ('skill:update'::text, 'skill'::text, 'update'::text, 'Update skill'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('competency:create'::text, 'competency'::text, 'create'::text, 'Create competency'::text),
            ('competency:delete'::text, 'competency'::text, 'delete'::text, 'Delete competency'::text),
            ('competency:purge'::text, 'competency'::text, 'purge'::text, 'Purge competency'::text),
            ('competency:read'::text, 'competency'::text, 'read'::text, 'Read competency'::text),
            ('competency:restore'::text, 'competency'::text, 'restore'::text, 'Restore competency'::text),
            ('competency:update'::text, 'competency'::text, 'update'::text, 'Update competency'::text),
            ('course:create'::text, 'course'::text, 'create'::text, 'Create course'::text),
            ('course:delete'::text, 'course'::text, 'delete'::text, 'Delete course'::text),
            ('course:purge'::text, 'course'::text, 'purge'::text, 'Purge course'::text),
            ('course:read'::text, 'course'::text, 'read'::text, 'Read course'::text),
            ('course:restore'::text, 'course'::text, 'restore'::text, 'Restore course'::text),
            ('course:update'::text, 'course'::text, 'update'::text, 'Update course'::text),
            ('course_enrollment:create'::text, 'course_enrollment'::text, 'create'::text, 'Create course enrollment'::text),
            ('course_enrollment:delete'::text, 'course_enrollment'::text, 'delete'::text, 'Delete course enrollment'::text),
            ('course_enrollment:purge'::text, 'course_enrollment'::text, 'purge'::text, 'Purge course enrollment'::text),
            ('course_enrollment:read'::text, 'course_enrollment'::text, 'read'::text, 'Read course enrollment'::text),
            ('course_enrollment:restore'::text, 'course_enrollment'::text, 'restore'::text, 'Restore course enrollment'::text),
            ('course_enrollment:update'::text, 'course_enrollment'::text, 'update'::text, 'Update course enrollment'::text),
            ('employee_competency:create'::text, 'employee_competency'::text, 'create'::text, 'Create employee competency'::text),
            ('employee_competency:delete'::text, 'employee_competency'::text, 'delete'::text, 'Delete employee competency'::text),
            ('employee_competency:purge'::text, 'employee_competency'::text, 'purge'::text, 'Purge employee competency'::text),
            ('employee_competency:read'::text, 'employee_competency'::text, 'read'::text, 'Read employee competency'::text),
            ('employee_competency:restore'::text, 'employee_competency'::text, 'restore'::text, 'Restore employee competency'::text),
            ('employee_competency:update'::text, 'employee_competency'::text, 'update'::text, 'Update employee competency'::text),
            ('employee_skill:create'::text, 'employee_skill'::text, 'create'::text, 'Create employee skill'::text),
            ('employee_skill:delete'::text, 'employee_skill'::text, 'delete'::text, 'Delete employee skill'::text),
            ('employee_skill:purge'::text, 'employee_skill'::text, 'purge'::text, 'Purge employee skill'::text),
            ('employee_skill:read'::text, 'employee_skill'::text, 'read'::text, 'Read employee skill'::text),
            ('employee_skill:restore'::text, 'employee_skill'::text, 'restore'::text, 'Restore employee skill'::text),
            ('employee_skill:update'::text, 'employee_skill'::text, 'update'::text, 'Update employee skill'::text),
            ('skill:create'::text, 'skill'::text, 'create'::text, 'Create skill'::text),
            ('skill:delete'::text, 'skill'::text, 'delete'::text, 'Delete skill'::text),
            ('skill:purge'::text, 'skill'::text, 'purge'::text, 'Purge skill'::text),
            ('skill:read'::text, 'skill'::text, 'read'::text, 'Read skill'::text),
            ('skill:restore'::text, 'skill'::text, 'restore'::text, 'Restore skill'::text),
            ('skill:update'::text, 'skill'::text, 'update'::text, 'Update skill'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
